function formatLogSection(log: SessionLog): string { const elapsed = `${Math.floor(log.elapsedMs / 60000)}m ${Math.floor((log.elapsedMs % 60000) / 1000)}s`; return `## Session ${log.timestamp.toISOString()}
- **Task**: #${log.taskId} ${log.taskTitle}
- **Backend**: ${log.backend}
- **Iterations**: ${log.iterations}
- **Outcome**: ${log.outcome}
- **Elapsed**: ${elapsed}
` }
